### Describe the bug


The on-disk cache key of a `@triton.jit` kernel (the key of the compiled kernels kept in `TRITON_CACHE_DIR` and reused by later compilations) leaves out information that changes the compiled kernel in many cases. Two kernels that differ only in such information get the same key, and the second one silently loads the binary compiled for the first, across processes (edit a value, rerun) and within one process (a factory). Each case below builds two kernels that differ only in one piece of information (as two runs with it edited in between) on one fresh cache directory; the first case, a `tl.constexpr` read by name, is in the key and is the control:

```python
import os
import subprocess
import sys
import tempfile
import types
from collections import namedtuple

os.environ["TRITON_CACHE_DIR"] = tempfile.mkdtemp()  # a fresh on-disk cache, shared by all kernels below
import torch
import triton
import triton.language as tl


def run(kernel, *args):
    o = torch.zeros(1, device="cuda")
    kernel[(1, )](o, *args)
    return o.item()


# Each case builds two kernels that differ only in one piece of information, as in two runs with it edited in between.
def by_name(v):  # control: a tl.constexpr read by name is in the key
    K = tl.constexpr(v)

    @triton.jit
    def kernel(o):
        tl.store(o, K)

    return run(kernel)


def module_attribute(v):
    global cfg
    cfg = types.ModuleType("cfg")
    cfg.K = tl.constexpr(v)

    @triton.jit
    def kernel(o):
        tl.store(o, cfg.K)

    return run(kernel)


def dtype_variable(v):
    DT = [tl.float16, tl.float32][v - 1]

    @triton.jit
    def kernel(o):
        tl.store(o, DT.primitive_bitwidth + tl.zeros((), DT).to(tl.float32))

    return run(kernel)


def builtin_variable(v):
    act = [tl.exp, tl.sqrt][v - 1]

    @triton.jit
    def kernel(o):
        tl.store(o, act(tl.full((), 4.0, tl.float32)))

    return run(kernel)


def helper_default(v):
    global K
    K = v

    @triton.jit
    def helper(k=K):
        return k

    @triton.jit
    def kernel(o):
        tl.store(o, helper())

    return run(kernel)


def aggregate_default(v):
    @triton.aggregate
    class Config:
        scale: tl.constexpr = v

    @triton.jit
    def kernel(o):
        tl.store(o, Config().scale)

    return run(kernel)


def namedtuple_default(v):
    Config = namedtuple("Config", ["scale"], defaults=[tl.constexpr(v)])

    @triton.jit
    def kernel(o):
        tl.store(o, Config().scale)

    return run(kernel)


@triton.jit
def class_arg_kernel(o, OP: tl.constexpr):
    tl.store(o, OP(tl.full((), 1.0, tl.float32)).apply())


def aggregate_class_argument(v):
    F = tl.constexpr(v)

    @triton.aggregate
    class Scale:
        x: tl.tensor

        @triton.jit
        def apply(self):
            return self.x * F

    return run(class_arg_kernel, Scale)


@triton.jit
def tuple_arg_kernel(o, FNS: tl.constexpr):
    tl.store(o, FNS[0](tl.full((), 0.0, tl.float32)))


def function_in_tuple_argument(v):
    C = tl.constexpr(v)

    @triton.jit
    def add(x):
        return x + C

    return run(tuple_arg_kernel, (add, ))


@triton.jit
def str_arg_kernel(o, A: tl.constexpr, B: tl.constexpr):
    tl.store(o, 1 if A == "x-y" else 2)


def arguments_that_print_alike(v):
    return run(str_arg_kernel, *[("x-y", "z"), ("x", "y-z")][v - 1])


CHILD = """
import torch, triton, triton.language as tl

@triton.jit
def k(x):
    tl.store(x, tl.load(x) * 2.0 + 1.0)

x = torch.ones(1, device="cuda")
k[(1, )](x)
print(x.item())
"""


def kernel_override(v):  # a run with TRITON_KERNEL_OVERRIDE=1 (the .ttir edited to 3 * x + 1), then a run without it
    d = os.environ["TRITON_CACHE_DIR"] + "_override"
    os.makedirs(d, exist_ok=True)
    open(f"{d}/p.py", "w").write(CHILD)

    def child(**env):
        env = {**os.environ, "TRITON_CACHE_DIR": f"{d}/cache", **env}
        return float(subprocess.run([sys.executable, f"{d}/p.py"], env=env, capture_output=True, text=True).stdout.split()[-1])

    if v == 1:
        child(TRITON_CACHE_DIR=f"{d}/cache_dump", TRITON_KERNEL_DUMP="1", TRITON_DUMP_DIR=f"{d}/dump")
        h = os.listdir(f"{d}/dump")[0]
        os.makedirs(f"{d}/override/{h}")
        ttir = open(f"{d}/dump/{h}/k.ttir").read().replace("2.000000e+00", "3.000000e+00")
        open(f"{d}/override/{h}/k.ttir", "w").write(ttir)
        return child(TRITON_KERNEL_OVERRIDE="1", TRITON_OVERRIDE_DIR=f"{d}/override")  # 3 * 1 + 1
    return child()  # without the override: 2 * 1 + 1 expected


bad = False
for case in [by_name, module_attribute, dtype_variable, builtin_variable, helper_default, aggregate_default, namedtuple_default,
             aggregate_class_argument, function_in_tuple_argument, arguments_that_print_alike, kernel_override]:
    first, second = case(1), case(2)
    same = first == second
    print(f"{case.__name__:28} first {first:<10.4g} second {second:<10.4g} {'SAME BINARY' if same else 'ok'}")
    bad |= same
sys.exit(1 if bad else 0)
```

Observed on main @23d6832c42 (exit code 1; 3.8.0 gives the same lines):
```
by_name                      first 1          second 2          ok
module_attribute             first 1          second 1          SAME BINARY
dtype_variable               first 16         second 16         SAME BINARY
builtin_variable             first 54.6       second 54.6       SAME BINARY
helper_default               first 1          second 1          SAME BINARY
aggregate_default            first 1          second 1          SAME BINARY
namedtuple_default           first 1          second 1          SAME BINARY
aggregate_class_argument     first 1          second 1          SAME BINARY
function_in_tuple_argument   first 1          second 1          SAME BINARY
arguments_that_print_alike   first 1          second 1          SAME BINARY
kernel_override              first 4          second 4          SAME BINARY
```

| case | the two kernels differ only in |
|---|---|
| `module_attribute` | a `tl.conste

### Name and Version

llama.cpp
Reference revision: b1ff4ca2 


### Operating systems

Linux

### GGML backends

CUDA

### Hardware

RTX 4080 SUPER, but not restricted to it.

### Models

Qwen3-1.7B Q4_K_M with Qwen3-1.7B EAGLE-3 draft.
But not restricted to a specific model.

### Problem description & steps to reproduce

# Problem description

If you plan a graph with `ggml_gallocr_reserve()` and then allocate a structurally identical graph with `ggml_gallocr_alloc_graph()` while changing the OUTPUT flag of some tensors with `ggml_set_output()`, the allocator never notices the change, and reuses the old plan.
Tensors without `GGML_TENSOR_FLAG_OUTPUT` can be reused after their last consumer finishes.
When concurrency > 1, this leads multiple intermediate tensors from different slots to share the same address. (And it's intended behavior)
However, if those tensors are later marked as outputs (`GGML_TENSOR_FLAG_OUTPUT`) and the graph is allocated without reserving again, the allocator reuses the old layout. As a result, multiple output tensors that **must remain live simultaneously** can be assigned **the same address** and the later writing overwrites earlier output values


`llm_graph_context::build_sampling()` creates this pattern exactly .
This is especially harmful in the EAGLE-3 draft as its context also re-reserves mid-run on a graph that has no sampler outputs

Specifically:
1. Reserve a graph while certain tensors are not marked as outputs. Their allocations can be reused after their last consumers. (in `process()`)
2. Allocate an equivalent graph in which those tensors are now marked as outputs. (in `draft()`)
3. The reuse checks pass because the node counts and tensor sizes still fit. (in `ggml_gallocr_alloc_graph()`)
4. The old address assignments are reused, despite the longer output lifetimes. (in `ggml_gallocr_alloc_graph()`)
5. Later computations overwrite outputs that must still be available for extraction. (in `graph_compute()` and `decode()`)



# Minimal reproduction (PoC)
Add test in `tests/test-alloc.cpp`
```
static void test_output_flag_changed_after_reserve() {
    dummy_backend    backend = dummy_backend_init(SIZE_MAX, /*align*/ 4);
    ggml_gallocr_ptr galloc  = ggml_gallocr_ptr(ggml_gallocr_new(&backend.buffer_type));

    // reserve while both top_k results are ordinary intermediates
    {
        auto [ctx, graph, ctx_ptr] = make_context();
        ggml_tensor * x = make_input_1d(ctx, 8);
        for (int r = 0; r < 2; ++r) {
            ggml_tensor * row  = ggml_view_1d(ctx, x, 4, r * 4 * sizeof(float));
            ggml_tensor * ids  = ggml_top_k(ctx, row, 1);
            ggml_tensor * vals = ggml_get_rows(ctx, ggml_reshape_2d(ctx, row, 1, 4), ids);
            ggml_build_forward_expand(graph, vals);
        }
        assign_names(ctx);
        GGML_ASSERT(ggml_gallocr_reserve(galloc.get(), graph));
    }

    // structurally identical graph, but now both top_k results are outputs
    {
        auto [ctx, graph, ctx_ptr] = make_context();
        ggml_tensor * x = make_input_1d(ctx, 8);
        ggml_tensor * ids[2];
        for (int r = 0; r < 2; ++r) {
            ggml_tensor * row  = ggml_view_1d(ctx, x, 4, r * 4 * sizeof(float));
            ids[r]             = ggml_top_k(ctx, row, 1);
            ggml_tensor * vals = ggml_get_rows(ctx, ggml_reshape_2d(ctx, row, 1, 4), ids[r]);
            ggml_set_output(ids[r]);
            ggml_build_forward_expand(graph, vals);
        }
        assign_names(ctx);

        GGML_ASSERT(ggml_gallocr_alloc_graph(galloc.get(), graph));
