// gatedPeekQueue holds the serve goroutine at its first Peek until the gate opens, so
// a test can cancel a request while it is still queued.
type gatedPeekQueue struct {
	fakeRouterQueue
	gate    chan struct{}
	started chan struct{}
	once    sync.Once
